-- Forward-only extension. Submission/decision rows and append-only triggers are untouched.
-- These are PostgreSQL's names generated by migration 048 (verified in migration tests).
ALTER TABLE customer_location_proposal_decisions
  DROP CONSTRAINT customer_location_proposal_decisions_decision_check,
  DROP CONSTRAINT customer_location_proposal_decisions_decided_by_role_check,
  ADD CONSTRAINT customer_location_proposal_decisions_decision_check
    CHECK (decision IN ('approved', 'rejected', 'withdrawn')),
  ADD CONSTRAINT customer_location_proposal_decisions_decided_by_role_check
    CHECK (decided_by_role IN ('admin', 'supervisor', 'inspector')),
  ADD COLUMN applied_patch JSONB NULL,
  ADD CONSTRAINT customer_location_proposal_decisions_patch_check
    CHECK (applied_patch IS NULL OR (decision = 'approved' AND jsonb_typeof(applied_patch) = 'object')),
  ADD CONSTRAINT customer_location_proposal_decisions_actor_check
    CHECK ((decision = 'withdrawn') = (decided_by_role = 'inspector'));
